-- Moved from app/V900.11.3__demo_remaining_tables.sql
SELECT u.user_id, NOW() - make_interval(days => (u.rn * 5)::int)
  FROM (
      SELECT user_id,
             ROW_NUMBER() OVER (ORDER BY user_id) AS rn
        FROM users
       ORDER BY user_id
       OFFSET 500 LIMIT 3
  ) u
ON CONFLICT (user_id) DO NOTHING;
